export function setupLayout(){
 const $=id=>document.getElementById(id),oldHeader=document.querySelector('header'),toolbar=document.createElement('header');toolbar.className='terminalToolbar';
 toolbar.innerHTML=`<a id="islandAnchor"></a><button data-menu="maMenu">均線設定⌄</button><button data-menu="orderMenu">下單設定⌄</button><button data-menu="speedMenu">速度設定⌄</button><button data-menu="dateMenu">日期設定⌄</button><button data-menu="alertMenu">警示設定 <kbd>Z</kbd></button><button id="todayRecords">本日進出紀錄</button><button id="historyOpen">歷史累積績效</button><button data-view="statistics">統計數據</button><span id="startAnchor"></span><button id="pause">暫停</button><button id="end">結束</button><span id="lightningAnchor"></span><button id="home" title="返回走勢圖">走勢圖</button>`;
 const move=(id,parent)=>{const el=$(id);parent.append(el);return el};
 const island=move('islandLink',toolbar.querySelector('#islandAnchor'));island.textContent='曾阿牛的冰火島 ↗';
 move('load',toolbar.querySelector('#startAnchor')).textContent='開始';move('popoutOrders',toolbar.querySelector('#lightningAnchor')).textContent='閃電下單 A';
 const status=document.createElement('div');status.className='terminalStatus';status.innerHTML='<strong>曾阿牛的期貨島</strong><span class="statusPosition"></span><span id="latestAlert" hidden role="status"></span><span class="terminalVersion">v0.9.6</span>';
 status.querySelector('.statusPosition').append(document.querySelector('.headerTrading'));move('status',status);document.body.insertBefore(toolbar,oldHeader);toolbar.after(status);
 const stash=document.createElement('div');stash.hidden=true;document.body.append(stash);stash.append(oldHeader);stash.append(document.querySelector('.toolbar'));stash.append(document.querySelector('.orderDock'));stash.append($('orderWindowPlaceholder'));stash.append($('play'));
 function menu(id,title,html){const d=document.createElement('dialog');d.id=id;d.className='settingDialog';d.innerHTML=`<div class="menuHead"><h2>${title}</h2><button data-dismiss aria-label="關閉${title}">×</button></div><div class="menuBody">${html}</div>`;document.body.append(d);d.querySelector('[data-dismiss]').onclick=()=>d.close();return d.querySelector('.menuBody')}
 const ma=menu('maMenu','均線設定','<p>勾選要顯示的均線，可選0～4條；週期以分鐘計。</p>');ma.append(document.querySelector('.maInputs'));document.getElementById('applyMA').addEventListener('click',()=>{const values=[1,2,3,4].map(i=>Number(document.getElementById('ma'+i).value));if(values.every((v,i)=>!document.getElementById('maVisible'+(i+1)).checked||(Number.isInteger(v)&&v>=1&&v<=300)))document.getElementById('maMenu').close()});$('ma3').value=15;const fourth=document.createElement('label');fourth.innerHTML='MA4<input id="ma4" aria-label="第四組均線週期" type="number" min="1" max="300" value="30">';ma.querySelector('.maInputs').insertBefore(fourth,$('applyMA'));for(let i=1;i<=4;i++){const label=$('ma'+i).closest('label'),check=document.createElement('input');check.type='checkbox';check.id='maVisible'+i;check.checked=true;check.setAttribute('aria-label','顯示第'+i+'條均線');const period=$('ma'+i),name=document.createElement('span');name.className='maName';name.textContent='MA'+i;label.replaceChildren(check,name,period)}const maActions=document.createElement('div');maActions.className='menuActions';maActions.append($('applyMA'));maActions.insertAdjacentHTML('beforeend','<button id="saveMA">儲存均線</button><button id="resetMA">重設均線</button>');ma.append(maActions);ma.insertAdjacentHTML('beforeend','<p id="maSaveState">儲存後下次開啟沿用；重設恢復5、10、15、30分鐘，並顯示四條均線。設定僅保存在目前瀏覽器。</p>');
 const order=menu('orderMenu','下單設定','<p>進出場與回測手法可於此設定。閃電下單支援現價、限價、停利停損與觸價；自動手法啟用期間由策略進場。</p><div id="methodAnchor"></div><div class="menuActions"><button id="modelSettings">資金與成交模型</button></div>');order.querySelector('#methodAnchor').append($('mode').closest('label'));order.querySelector('#modelSettings').onclick=()=>{$('orderMenu').close();document.querySelector('[data-view="settings"]').click()};
 const speed=menu('speedMenu','速度設定','<p>只改變回放速度，每筆行情均會判定。</p>');speed.append($('speed'));$('speed').insertAdjacentHTML('beforeend','<option value="2">兩倍速</option><option value="50">50倍速</option>');[...$('speed').options].sort((a,b)=>Number(a.value)-Number(b.value)).forEach(x=>$('speed').append(x));
 const date=menu('dateMenu','日期設定','<label>選擇方式<select id="dateMode"><option value="random" selected>隨機日期</option><option value="specified">指定日期</option></select></label><div id="dateAnchor"></div><p>指定日期後按「播放」，會從所選日期的第一筆行情開始回放。</p><div class="menuActions"><button id="applyDate" class="primary" type="button">▶ 播放</button><button id="startNew">重新抽選／新練習</button></div>');for(const id of ['date','contract','blind'])date.querySelector('#dateAnchor').append($(id).closest('label'));$('date').disabled=true;date.closest('dialog').append(date.querySelector('.menuActions'));
 menu('alertMenu','警示設定',`<p>預設關閉。每個勾選條件各自通知一次；同時成立會各別顯示，之後震盪重複觸發會忽略。新練習才重設。依每筆成交即時判斷，觸及即通知，不等K棒收盤。</p><fieldset><legend>當日震幅</legend><label class="alertCheck"><input id="alertAmplitude" type="checkbox">震幅達到<input id="alertAmplitudePoints" type="number" value="300" min="1" aria-label="震幅警示點數">點時通知一次</label><p>以已播放行情的最高價減最低價計算。</p></fieldset><fieldset><legend>開盤價距離</legend><label class="alertCheck"><input type="checkbox" id="alertOpenUp">開盤價＋<input type="number" id="alertUpPoints" value="30" min="1" aria-label="開盤價上方點數">點通知</label><label class="alertCheck"><input type="checkbox" id="alertOpenDown">開盤價－<input type="number" id="alertDownPoints" value="30" min="1" aria-label="開盤價下方點數">點通知</label></fieldset><fieldset><legend>開盤至指定上午時間</legend><label>區間結束時間<input id="alertTime" type="time" min="08:45" max="11:59" value="09:30"></label><p>含指定分鐘的完整行情，下一分鐘起判斷。</p><label class="alertCheck"><input id="alertRangeUp" type="checkbox">觸及／突破區間最高價時通知</label><label class="alertCheck"><input id="alertRangeDown" type="checkbox">觸及／跌破區間最低價時通知</label></fieldset><fieldset><legend>昨日高低點</legend><p>觸發後顯示曾達到的最大上行／下行點數，行情回落不減少；再創新高／新低才增加。每個條件仍只通知一次。</p><p>今日08:45開盤介於昨日高低價之間才成立。</p><p id="yesterdayReference">待載入</p><label class="alertCheck"><input id="alertYesterdayUp" type="checkbox">觸及／突破昨日最高價時通知</label><label class="alertCheck"><input id="alertYesterdayDown" type="checkbox">觸及／跌破昨日最低價時通知</label></fieldset><p id="alertState">所有警示均關閉</p><div class="menuActions"><button id="applyAlerts" class="primary">套用警示</button><button id="saveAlerts">儲存警示</button><button id="resetAlertSettings">重設警示</button></div><p id="alertSaveState">儲存後下次開啟沿用；重設會儲存預設值並關閉全部警示。本次已通知條件僅在新練習重設。</p><h3>本次通知紀錄</h3><div id="alertLog" class="alertLog"></div>`);
 const ledger=menu('ledgerDialog','本日進出紀錄','<div class="menuActions" id="saveAnchor"></div>');ledger.append(document.querySelector('.ledger'));for(const id of ['save'])move(id,ledger.querySelector('#saveAnchor'));
 for(const b of toolbar.querySelectorAll('[data-menu]'))b.onclick=()=>$(b.dataset.menu).showModal();
 for(const d of document.querySelectorAll('.settingDialog'))d.addEventListener('click',e=>{if(e.target===d){const b=d.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)d.close()}});
 const performance=menu('performanceDialog','本日績效','<div id="dailyPerformanceContent"></div><div class="menuActions"><button id="savePerformance" class="primary">儲存本日績效</button></div><p id="performanceSaved"></p>');
 const chart=document.querySelector('.chartpanel');const position=document.createElement('div');position.id='positionStrip';position.className='positionStrip';position.innerHTML='<strong id="stripSide">空手 0口</strong><span id="stripCost">成本均價 —</span><span id="stripPNL">即時損益 TWD 0</span><button id="stripClose" disabled>平倉</button><button id="dailyPerformance">本日績效</button><button id="saveChart" title="儲存已播放走勢與進出場點位；下載位置依瀏覽器設定">儲存走勢圖</button><span class="shortcutHelp">快捷鍵：警示設定 Z · 閃電下單 A · 刪單 D</span>';document.querySelector('.chartTools').prepend(position);chart.querySelector('.charthead').append($('guideBtn'));document.querySelector('.chartTools').querySelector('.zoomControls').append($('step'),$('minute'),$('nextEvent'));chart.querySelector('.playback').hidden=true;chart.querySelector('.chartNavigator').append($('progress'));document.querySelector('.bottomnote').hidden=true;
 const summary=document.createElement('div');summary.id='historySummary';summary.className='notice';$('historyList').before(summary);document.querySelector('#history h1').textContent='歷史累積績效';const aggregate=document.createElement('section');aggregate.id='historyAggregate';aggregate.className='panel historyAggregate';document.querySelector('#history .toolbar').before(aggregate);const timeAnalysis=document.createElement('section');timeAnalysis.id='entryTimeAnalysis';timeAnalysis.className='panel statisticsPanel entryTimeAnalysis';aggregate.after(timeAnalysis);const historyActions=document.querySelector('#history .pagehead>div:last-child');historyActions.classList.add('historyHeadActions');const back=document.createElement('button');back.type='button';back.dataset.view='practice';back.textContent='← 返回走勢圖';historyActions.append(back);const notices=document.createElement('div');notices.id='alertNotices';notices.className='alertNotices';document.body.append(notices);const stats=document.createElement('section');stats.id='statistics';stats.className='view hidden';stats.innerHTML='<div class="pagehead"><div><h1>統計數據</h1><p>TX 日盤行情統計</p></div><button data-view="practice">← 返回走勢圖</button></div>';const statsBody=document.createElement('div');statsBody.id='statisticsContent';statsBody.innerHTML='<p>正在讀取統計數據…</p>';stats.append(statsBody);document.querySelector('main').append(stats);document.body.classList.add('terminal');
}
